import{_ as e,o as t,c as p,a0 as o}from"./chunks/framework.jwovEGr5.js";const h=JSON.parse('{"title":"消防安全（实践）","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"中山大学/新生体验/消防安全（实践）.md","filePath":"中山大学/新生体验/消防安全（实践）.md"}'),l={name:"中山大学/新生体验/消防安全（实践）.md"};function r(i,a,_,n,s,c){return t(),p("div",null,[...a[0]||(a[0]=[o('<h1 id="消防安全-实践" tabindex="-1">消防安全（实践） <a class="header-anchor" href="#消防安全-实践" aria-label="Permalink to &quot;消防安全（实践）&quot;">​</a></h1><p>课程时间：2026.8.23 14:30~16:00</p><p>课程地点：中山大学英东体育场</p><h2 id="活动内容" tabindex="-1">活动内容 <a class="header-anchor" href="#活动内容" aria-label="Permalink to &quot;活动内容&quot;">​</a></h2><ol><li>讲解防烟面罩的使用</li></ol><p>正式名称：过滤式消防自救呼吸器</p><p>打开塑料盒子，面罩在真空包装袋中，撕开包装袋取出面罩</p><p>嘴部的两面都有橡皮塞，拔开橡皮塞（两面都拔），之后套到头上，系紧带子</p><blockquote><p>头发长要全部塞进面罩之中，防止烟尘进入面罩</p></blockquote><ol start="2"><li>讲解灭火器的使用（干粉灭火器）</li><li>灭火水枪的使用</li><li>充气式消防逃生体验屋</li></ol><p>介绍：</p><p>整体是充气气模，内部有充气隔断，造出弯弯绕绕迷宫式通道，有独立入口、出口</p><p>搭配安全无毒的演练发烟机，放出白色模拟浓烟，内部变暗，有的还加火灾警报音效，模拟火场充满烟雾的楼道环境</p><p>体验者进去必须弯腰低姿、捂口鼻，沿着疏散指示标志摸索找到出口</p><p>现场情况：</p><p>并没有模拟浓烟，也无指示标志，同学多，有点像走迷宫</p><ol start="5"><li>消防人员的工具介绍</li></ol><p>无齿锯：高速切割钢筋、混凝土、铁门</p><p>机动链锯：切割木头</p><p>太平斧、撬棍：劈门撬锁</p>',20)])])}const u=e(l,[["render",r]]);export{h as __pageData,u as default};
